import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer f = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(f.nextToken());
        int amount = Integer.parseInt(f.nextToken());
        StringTokenizer tk = new StringTokenizer(br.readLine());
        int[] coins = new int[n];
        for (int i = 0; i < n; i++) coins[i] = Integer.parseInt(tk.nextToken());
        final int INF = 1_000_000_000;
        int[] dp = new int[amount + 1];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int a = 1; a <= amount; a++)
            for (int c : coins)
                if (c <= a && dp[a - c] + 1 < dp[a]) dp[a] = dp[a - c] + 1;
        int answer = dp[amount] >= INF ? -1 : dp[amount];
        System.out.println(answer);
    }
}
